head.script:
// gridView advancedExcelDownload sheetIndex 옵션 검증 샘플
//
// sheetIndex 는 기존 Excel 파일을 편집할 때 새 sheet 를 넣을 위치다.
// 따라서 editMode:true 를 함께 지정한다. sheetIndex 외의 옵션은 기존과 동일하게 둔다.
//
// 기대 payload : <data hashkey='sheetIndex' value='0'/>
//   미지정 / null / 빈 문자열 -> 요청에서 생략
//   0 및 양수                 -> 값 그대로 전달 (엔진은 보정하지 않는다)

scwin.onpageload = function() {
    dataList1.setJSON([
        { region: "서울", industry: "제조", amount: 100 },
        { region: "부산", industry: "서비스", amount: 200 }
    ]);
};

scwin.download = function(fileName, sheetIndex, sheetName) {
    var options = {
        fileName: fileName,
        extension: "xlsx",
        showDialog: false,
        useXHR: true,
        editMode: true
    };
    if (typeof sheetIndex !== "undefined") {
        options.sheetIndex = sheetIndex;
    }
    if (typeof sheetName !== "undefined") {
        options.sheetName = sheetName;
    }
    gridView1.advancedExcelDownload(options);
};

// 1) 미지정 : 요청에서 sheetIndex 가 생략돼야 한다
scwin.downloadUnspecified = function() {
    scwin.download("sheetIndex_unspecified.xlsx", undefined);
};

// 2) 0 : 생략되지 않고 그대로 전달돼야 한다
scwin.downloadZero = function() {
    scwin.download("sheetIndex_0.xlsx", 0);
};

// 3) 양수
scwin.downloadPositive = function() {
    scwin.download("sheetIndex_2.xlsx", 2);
};

// 4) sheetName 과 동시 지정 : 이름과 위치가 각각 독립적으로 전달돼야 한다
scwin.downloadWithSheetName = function() {
    scwin.download("sheetIndex_with_name.xlsx", 1, "신규시트");
};

// 5) null : 요청에서 생략돼야 한다
scwin.downloadNull = function() {
    scwin.download("sheetIndex_null.xlsx", null);
};

// 6) 빈 문자열 : 요청에서 생략돼야 한다
scwin.downloadEmpty = function() {
    scwin.download("sheetIndex_empty.xlsx", "");
};

// 7) 다중 sheet : 각 sheet 정보에 지정한 sheetIndex 가 전달돼야 한다
scwin.downloadMultiSheet = function() {
    WebSquare.util.multipleDataListDownload({
        common: {
            fileName: "sheetIndex_multi.xlsx",
            multipleSheet: true,
            showProcess: false,
            useXHR: true,
            editMode: true
        },
        excelInfo: [
            { dataListId: "dataList1", sheetName: "첫번째", sheetIndex: 0 },
            { dataListId: "dataList1", sheetName: "두번째", sheetIndex: 3 }
        ]
    });
};
